fn read_value(reader:&mut Reader<'_>,id:i64,c:&mut SqliteSnapshotControl<'_>)->Result<CatalogueValue, ValueError>{enum Step<'a>{Visit(i64),Finish(FloatRow<'a>,Vec<i64>)}let mut stack=vec![Step::Visit(id)];let mut values=ValueOwners(BTreeMap::new());let mut units=0;while let Some(step)=stack.pop(){checkpoint(c,units,0)?;units+=1;match step{Step::Visit(id)=>{let r=reader.take("iso16757_catalogue_value",id)?;let rows=reader.ordered("iso16757_value_element",id,c)?;let mut children=Vec::new();for a in rows{children.push(a.integer(3)?);}if r.text(1)?!="List"&&!children.is_empty(){return Err(invalid("ISO scalar catalogue value owns list elements"));}c.check_rows(stack.len().checked_add(children.len()).ok_or_else(|| ValueError::new(ValueRefusalKind::WorkLimit, "ISO value reconstruction frontier overflow"))?)?;stack.push(Step::Finish(r,children.clone()));for child in children.into_iter().rev(){stack.push(Step::Visit(child));}},Step::Finish(r,children)=>{let kind=r.text(1)?;let value=match kind{"Boolean"=>{active(r,&[2])?;CatalogueValue::Boolean{value:boolean(r,2)?}},"Integer"=>{active(r,&[3])?;CatalogueValue::Integer{value:r.integer(3)?}},"Decimal"=>{active(r,&[4])?;CatalogueValue::Decimal{value:r.real(4)?}},"Text"=>{active(r,&[5])?;CatalogueValue::Text{value:text(r,5,c)?}},"Identifier"=>{active(r,&[5])?;CatalogueValue::Identifier{value:text(r,5,c)?}},"Enumeration"=>{active(r,&[5])?;CatalogueValue::Enumeration{value:text(r,5,c)?}},"Controlled"=>{active(r,&[5,6])?;CatalogueValue::Controlled{value:text(r,5,c)?,list_id:text(r,6,c)?}},"Quantity"=>{active(r,&[4,7])?;CatalogueValue::Quantity{value:r.real(4)?,unit:read_unit(reader,r.integer(7)?,c)?}},"Range"=>{active(r,&[7,8,9])?;CatalogueValue::Range{min:r.real(8)?,max:r.real(9)?,unit:read_optional_unit(reader,r,7,c)?}},"Null"=>{active(r,&[10])?;CatalogueValue::Null{state:match r.text(10)?{"Unavailable"=>NullState::Unavailable,"Unknown"=>NullState::Unknown,"NotApplicable"=>NullState::NotApplicable,_=>return Err(invalid("ISO null s