fn add(rows:&mut usize,count:usize,maximum:usize,c:&mut NativeEncodeControl<'_>)->Result<(),ValueError>{*rows=rows.checked_add(count).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"ISO entity count overflow"))?;if *rows>maximum{return Err(invalid("ISO native entity row limit exceeded"))}c.step()}
fn names(v:&Names,rows:&mut usize,maximum:usize,c:&mut NativeEncodeControl<'_>)->Result<(),ValueError>{add(rows,1,maximum,c)?;add(rows,v.alternatives.len(),maximum,c)}
fn value(v:&CatalogueValue,rows:&mut usize,maximum:usize,c:&mut NativeEncodeControl<'_>)->Result<(),ValueError>{c.scoped_depth(64,|c|{add(rows,1,maximum,c)?;match v{CatalogueValue::Quantity{..}|CatalogueValue::Range{unit:Some(_),..}=>add(rows,1,maximum,c)?,CatalogueValue::List{items}=>{add(rows,items.len(),maximum,c)?;for v in items{value(v,rows,maximum,c)?;}},_=>{}}Ok(())})}
fn property(v:&part_1::PropertyValue,rows:&mut usize,maximum:usize,c:&mut NativeEncodeControl<'_>)->Result<(),ValueError>{add(rows,2,maximum,c)?;value(&v.value,rows,maximum,c)}
fn node(v:&part_2::GeometryNode,rows:&mut usize,maximum:usize,c:&mut NativeEncodeControl<'_>)->Result<(),ValueError>{c.scoped_depth(64,|c|{add(rows,1,maximum,c)?;match v{part_2::GeometryNode::Primitive{parameters,..}=>add(rows,parameters.len(),maximum,c)?,part_2::GeometryNode::Transform{child,..}=>{add(rows,1,maximum,c)?;node(child,rows,maximum,c)?;},part_2::GeometryNode::Boolean{children,..}=>{add(rows,children.len(),maximum,c)?;for v in children{node(v,rows,maximum,c)?;}},part_2::GeometryNode::Reference{..}=>{}}Ok(())})}
fn extension(v:&DslValue,rows:&mut usize,maximum:usize,c:&mut NativeEncodeControl<'_>)->Result<(),ValueError>{c.scoped_depth(64,|c|{add(rows,1,maximum,c)?;match v{semio_framework_value::DslValue::Array(items)=>{add(rows,items.len(),maximum,c)?;for v in items{extension(v,rows,maximum,c)?;}},semio_framework_value::DslValue::Object(items)=>{add(rows,items.len(),maximum,c)?;for(_,v)in items{extension(v,rows,maximum,c)?;}},_=>{}}Ok(())})}
/// 📇️ Counts each authored entity occurrence without materializing a second document.
pub fn admit_rows(s:&Iso16757Snapshot,c:&mut NativeEncodeControl<'_>,maximum:usize)->Result<(),ValueError>{c.scoped_stage(|c|{
 c.begin_stage(0)?;let mut rows=0usize;add(&mut rows,1,maximum,c)?;let cat=&s.catalogue;names(&cat.metadata.names,&mut rows,maximum,c)?;names(&cat.manufacturer.names,&mut rows,maximum,c)?;
 for v in &cat.product_groups{add(&mut rows,1,maximum,c)?;names(&v.names,&mut rows,maximum,c)?;}
 for v in &cat.product_classes{add(&mut rows,1,maximum,c)?;names(&v.names,&mut rows,maximum,c)?;add(&mut rows,v.required_property_ids.len(),maximum,c)?;add(&mut rows,v.optional_property_ids.len(),maximum,c)?;}
 for v in &cat.product_series{add(&mut rows,1,maximum,c)?;names(&v.names,&mut rows,maximum,c)?;for v in v.shared_property_values.values(){add(&mut rows,1,maximum,c)?;value(v,&mut rows,maximum,c)?;}}
 for v in &cat.products{add(&mut rows,1,maximum,c)?;names(&v.names,&mut rows,maximum,c)?;for v in &v.parameter_domains{add(&mut rows,1,maximum,c)?;if let Some(v)=&v.default_value{value(v,&mut rows,maximum,c)?;}for v in &v.allowed_values{add(&mut rows,1,maximum,c)?;value(v,&mut rows,maximum,c)?;}}for v in &v.variants{add(&mut rows,1,maximum,c)?;for v in v.parameter_values.values(){add(&mut rows,1,maximum,c)?;value(v,&mut rows,maximum,c)?;}for v in &v.property_values{property(v,&mut rows,maximum,c)?;}}for v in &v.static_properties{property(v,&mut rows,maximum,c)?;}}
 for v in &cat.product_indexes{add(&mut rows,1,maximum,c)?;add(&mut rows,v.search_tags.len(),maximum,c)?;}
 for v in &cat.property_definitions{add(&mut rows,1+usize::from(v.unit.is_some()),maximum,c)?;names(&v.names,&mut rows,maximum,c)?;}
 for values in cat.accessories.values(){add(&mut rows,1,maximum,c)?;add(&mut rows,values.len(),maximum,c)?;}for values in cat.compositions.values(){add(&mut rows,1,maximum,c)?;add(&mut rows,values.len(),maximum,c)?;}add(&mut rows,cat.descriptive_objects.len(),maximum,c)?;
 for v in cat.extensions.fields.values(){add(&mut rows,1,maximum,c)?;extension(v,&mut rows,maximum,c)?;}
 let dictionary=&s.dictionary;for v in dictionary.subjects.iter().chain(&dictionary.meta_subjects){add(&mut rows,1,maximum,c)?;names(&v.names,&mut rows,maximum,c)?;}add(&mut rows,dictionary.relationships.len(),maximum,c)?;
 for v in &dictionary.properties{add(&mut rows,1+usize::from(v.unit.is_some()),maximum,c)?;names(&v.names,&mut rows,maximum,c)?;add(&mut rows,v.applicable_subject_ids.len(),maximum,c)?;for v in &v.value_constraints{add(&mut rows,1,maximum,c)?;add(&mut rows,v.allowed_values.len(),maximum,c)?;}}
 for v in &dictionary.controlled_lists{add(&mut rows,1,maximum,c)?;add(&mut rows,v.values.len(),maximum,c)?;add(&mut rows,v.context_subject_ids.len(),maximum,c)?;}
 for v in s.geometry.objects.values(){add(&mut rows,1,maximum,c)?;if let Some(v)=&v.shape{node(v,&mut rows,maximum,c)?;}if let Some(v)=&v.symbolic{node(v,&mut rows,maximum,c)?;}for count in[v.spaces.len(),v.surfaces.len(),v.ports.len(),v.parameter_bindings.len()]{add(&mut rows,count,maximum,c)?;}}
 for v in &s.geometry.primitive_registry{add(&mut rows,1,maximum,c)?;add(&mut rows,v.parameters.len(),maximum,c)?;}
 for v in &s.selection.constraints{add(&mut rows,1,maximum,c)?;value(&v.value,&mut rows,maximum,c)?;}
 if let part_5::PartNumberRule::Table{rows:values,..}=&s.part_number_rule{for v in values{add(&mut rows,1,maximum,c)?;add(&mut rows,v.len(),maximum,c)?;}}
 for v in s.part_number_inputs.values(){add(&mut rows,1,maximum,c)?;value(v,&mut rows,maximum,c)?;}c.checkpoint()
})}

//! 📏️ Explicit borrowed native encoding admission for the retained ISO catalogue model.
use crate::{Iso16757Snapshot,CatalogueValue,CatalogueUnit,Names,part_1,part_2,part_5};
use store::sqlite_snapshot::{SqliteSnapshotControl,artifact::NativeEncodingBound};
use semio_framework_value::ValueError;
struct Bound<'a,'b>{native:NativeEncodingBound<'a,'b>,rows:usize}
impl<'a,'b> Bound<'a,'b>{
 fn row(&mut self)->Result<(),ValueError>{self.rows=self.rows.checked_add(1).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"ISO native entity bound overflow"))?;self.native.check_rows(self.rows)?;self.native.add(8192)}
 fn text(&mut self,v:&str)->Result<(),ValueError>{self.native.repeated(v.len(),24)}
 fn strings(&mut self,v:&[&str])->Result<(),ValueError>{for value in v{self.text(value)?;}Ok(())}
 fn optional(&mut self,v:&Option<String>)->Result<(),ValueError>{if let Some(v)=v{self.text(v)?;}Ok(())}
 fn list(&mut self,v:&[String])->Result<(),ValueError>{self.native.check_rows(self.rows.checked_add(v.len()).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"ISO native list bound overflow"))?)?;for v in v{self.row()?;self.text(v)?;}Ok(())}
 fn names(&mut self,v:&Names)->Result<(),ValueError>{self.row()?;self.strings(&[&v.preferred.locale,&v.preferred.text])?;self.optional(&v.short_name)?;self.native.check_rows(self.rows.checked_add(v.alternatives.len()).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"ISO native names bound overflow"))?)?;for a in &v.alternatives{self.row()?;self.strings(&[&a.locale,&a.text])?;}Ok(())}
 fn unit(&mut self,v:&CatalogueUnit)->Result<(),ValueError>{self.row()?;self.text(&v.symbol)}
 fn value(&mut self,v:&CatalogueValue)->Result<(),ValueError>{let mut stack=vec![(v,0usize)];while let Some((v,depth))=stack.pop(){self.row()?;self.native.repeated(depth,64)?;match v{CatalogueValue::Text{value}|CatalogueValue::Identifier{value}|CatalogueValue::Enumeration{value}=>self.text(value)?,CatalogueValue::Controlled{value,list_id}=>self.strings(&[value,list_id])?,CatalogueValue::Quantity{unit,..}=>self.unit(unit)?,CatalogueValue::Range{unit:Some(unit),..}=>self.unit(unit)?,CatalogueValue::Reference{target_id}=>self.text(target_id)?,CatalogueValue::List{items}=>{self.native.check_rows(self.rows.checked_add(stack.len()).and_then(|n|n.checked_add(items.len())).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"ISO native value frontier overflow"))?)?;self.native.checkpoint()?;let next=depth.checked_add(1).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"ISO native depth overflow"))?;for item in items{stack.push((item,next));}},_=>{}}}Ok(())}
 fn property(&mut self,v:&part_1::PropertyValue)->Result<(),ValueError>{self.row()?;self.text(&v.definition_id)?;self.optional(&v.function_id)?;self.value(&v.value)}
 fn node(&mut self,v:&part_2::GeometryNode)->Result<(),ValueError>{let mut stack=vec![(v,0usize)];while let Some((v,depth))=stack.pop(){self.row()?;self.native.repeated(depth,64)?;match v{part_2::GeometryNode::Primitive{kind,parameters}=>{self.text(kind)?;self.native.check_rows(self.rows.checked_add(parameters.len()).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"ISO native parameter bound overflow"))?)?;for key in parameters.keys(){self.row()?;self.text(key)?;}},part_2::GeometryNode::Reference{geometry_id}=>self.text(geometry_id)?,part_2::GeometryNode::Transform{child,..}=>{self.native.checkpoint()?;stack.push((child,depth.checked_add(1).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"ISO native depth overflow"))?));},part_2::GeometryNode::Boolean{children,..}=>{self.native.check_rows(self.rows.checked_add(stack.len()).and_then(|n|n.checked_add(children.len())).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"ISO native geometry frontier overflow"))?)?;self.native.checkpoint()?;let next=depth.checked_add(1).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"ISO native depth overflow"))?;for child in children{stack.push((child,next));}}}}Ok(())}
 fn extension(&mut self,v:&semio_framework_value::DslValue)->Result<(),ValueError>{let mut stack=vec![(v,0usize)];while let Some((v,depth))=stack.pop(){self.row()?;self.native.repeated(depth,64)?;match v{semio_framework_value::DslValue::String(v)=>self.text(v)?,semio_framework_value::DslValue::Bytes(v)=>self.native.repeated(v.len(),24)?,semio_framework_value::DslValue::Array(items)=>{self.native.check_rows(self.rows.checked_add(stack.len()).and_then(|n|n.checked_add(items.len())).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"ISO native extension frontier overflow"))?)?;self.native.checkpoint()?;let next=depth.checked_add(1).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"ISO native depth overflow"))?;for item in items{stack.push((item,next));}},semio_framework_value::DslValue::Object(items)=>{self.native.check_rows(self.rows.checked_add(stack.len()).and_then(|n|n.checked_add(items.len())).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"ISO native extension frontier overflow"))?)?;self.native.checkpoint()?;let next=depth.checked_add(1).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"ISO native depth overflow"))?;for(key,item)in items{self.text(key)?;stack.push((item,next));}},_=>{}}}Ok(())}
}
pub fn preflight(s:&Iso16757Snapshot,c:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{
 let mut b=Bound{native:NativeEncodingBound::new(c)?,rows:0};b.row()?;let v=&s.catalogue;b.strings(&[&v.id.0,&v.metadata.lifecycle.revision,&v.metadata.lifecycle.status,&v.manufacturer.id,&v.dictionary.id,&v.dictionary.version])?;b.optional(&v.metadata.lifecycle.valid_from)?;b.optional(&v.metadata.lifecycle.valid_to)?;b.names(&v.metadata.names)?;b.names(&v.manufacturer.names)?;
 for v in &s.catalogue.product_groups{b.row()?;b.text(&v.id)?;b.names(&v.names)?;b.optional(&v.dictionary_subject_id)?;}
 for v in &s.catalogue.product_classes{b.row()?;b.strings(&[&v.id,&v.group_id])?;b.optional(&v.parent_id)?;b.names(&v.names)?;b.list(&v.required_property_ids)?;b.list(&v.optional_property_ids)?;}
 for v in &s.catalogue.product_series{b.row()?;b.strings(&[&v.id,&v.class_id])?;b.names(&v.names)?;b.optional(&v.geometry_id)?;for(key,value)in &v.shared_property_values{b.row()?;b.text(key)?;b.value(value)?;}}
 for v in &s.catalogue.products{b.row()?;b.strings(&[&v.id,&v.series_id])?;b.names(&v.names)?;for d in &v.parameter_domains{b.row()?;b.text(&d.parameter_id)?;for v in &d.allowed_values{b.value(v)?;}if let Some(v)=&d.default_value{b.value(v)?;}}for v in &v.variants{b.row()?;b.text(&v.id)?;b.optional(&v.article_number)?;b.optional(&v.geometry_id)?;for(key,v)in &v.parameter_values{b.row()?;b.text(key)?;b.value(v)?;}for p in &v.property_values{b.property(p)?;}}for p in &v.static_properties{b.property(p)?;}}
 for v in &s.catalogue.product_indexes{b.row()?;b.strings(&[&v.id,&v.product_id])?;b.optional(&v.variant_id)?;b.list(&v.search_tags)?;}
 for v in &s.catalogue.property_definitions{b.row()?;b.strings(&[&v.id,&v.data_type])?;b.names(&v.names)?;if let Some(u)=&v.unit{b.unit(u)?;}b.optional(&v.dictionary_property_id)?;}
 for(key,v)in &s.catalogue.accessories{b.row()?;b.text(key)?;for a in v{b.row()?;b.text(&a.accessory_product_id)?;b.optional(&a.compatibility_condition)?;}}
 for(key,v)in &s.catalogue.compositions{b.row()?;b.text(key)?;for a in v{b.row()?;b.text(&a.component_product_id)?;}}
 for v in &s.catalogue.descriptive_objects{b.row()?;b.strings(&[&v.id,&v.media_type,&v.uri])?;b.optional(&v.language)?;b.optional(&v.checksum)?;}
 for(key,v)in &s.catalogue.extensions.fields{b.row()?;b.text(key)?;b.extension(v)?;}
 b.strings(&[&s.dictionary.reference.id,&s.dictionary.reference.version])?;
 for v in s.dictionary.subjects.iter().chain(&s.dictionary.meta_subjects){b.row()?;b.strings(&[&v.id,&v.definition.locale,&v.definition.text])?;b.names(&v.names)?;b.optional(&v.parent_id)?;}
 for v in &s.dictionary.relationships{b.row()?;b.strings(&[&v.id,&v.source_id,&v.target_id])?;}
 for v in &s.dictionary.properties{b.row()?;b.strings(&[&v.id,&v.data_type])?;b.names(&v.names)?;if let Some(u)=&v.unit{b.unit(u)?;}b.list(&v.applicable_subject_ids)?;for c in &v.value_constraints{b.row()?;b.list(&c.allowed_values)?;}}
 for v in &s.dictionary.controlled_lists{b.row()?;b.text(&v.id)?;b.list(&v.values)?;b.list(&v.context_subject_ids)?;}
 for(key,v)in &s.geometry.objects{b.row()?;b.strings(&[key,&v.id])?;if let Some(n)=&v.shape{b.node(n)?;}if let Some(n)=&v.symbolic{b.node(n)?;}for a in &v.spaces{b.row()?;b.text(&a.id)?;}for a in &v.surfaces{b.row()?;b.strings(&[&a.id,&a.purpose])?;}for a in &v.ports{b.row()?;b.strings(&[&a.id,&a.medium,&a.port_type])?;}for(parameter,property)in &v.parameter_bindings{b.row()?;b.strings(&[parameter,property])?;}}
 for v in &s.geometry.primitive_registry{b.row()?;b.text(&v.id)?;b.list(&v.parameters)?;}
 b.text(&s.selection.class_id)?;b.optional(&s.selection.series_id)?;for v in &s.selection.constraints{b.row()?;b.strings(&[&v.id,&v.property_id])?;b.value(&v.value)?;}
 match &s.part_number_rule{part_5::PartNumberRule::Literal{value}=>b.text(value)?,part_5::PartNumberRule::Script{function_id,source}=>b.strings(&[function_id,source])?,part_5::PartNumberRule::Table{rows,output_column}=>{b.text(output_column)?;for row in rows{b.row()?;for(key,value)in row{b.row()?;b.strings(&[key,value])?;}}}}
 for(key,value)in &s.part_number_inputs{b.row()?;b.text(key)?;b.value(value)?;}
 b.native.finish()
}
